-- ════════════════════════════════════════════════
-- SETUP COMPLETO · PAINEL ACORDOS TRADE
-- Drogaria Globo · Base 2026
-- ════════════════════════════════════════════════
-- Execute este arquivo UMA ÚNICA VEZ no SQL Editor
-- do Supabase. Ele faz tudo:
--   1) cria as 3 tabelas que o painel usa
--   2) libera o acesso público de leitura e escrita
--   3) carrega os 114 acordos e 410 parcelas
-- ════════════════════════════════════════════════

-- ── 1. TABELAS ──

create table if not exists acordos_trade (
  id uuid primary key default gen_random_uuid(),
  n_acordo text,
  nome text not null,
  industria text not null,
  trade text not null,
  valor_total numeric(14,2) not null,
  qtde_parcelas int not null default 1,
  cat_visibilidade text,
  visibilidade text,
  valor_visibilidade numeric(14,2) default 0,
  tipo_parcela text default 'fixo',
  status_plano int default 1,
  criado_em timestamptz default now(),
  atualizado_em timestamptz default now()
);

create table if not exists parcelas_acordo (
  id uuid primary key default gen_random_uuid(),
  acordo_id uuid references acordos_trade(id) on delete cascade,
  numero int not null,
  competencia text,
  execucao text,
  recibo text,
  valor_previsto numeric(14,2) default 0,
  valor_recebido numeric(14,2) default 0,
  status text default 'previsto',
  recebido_em timestamptz,
  recebido_por text,
  criado_em timestamptz default now(),
  atualizado_em timestamptz default now()
);

create table if not exists kb_tarefas (
  id uuid primary key default gen_random_uuid(),
  titulo text not null,
  descricao text,
  trade text not null,
  fornecedor text,
  prioridade text default 'media',
  data date,
  status text default 'todo',
  criado_em timestamptz default now(),
  atualizado_em timestamptz default now()
);

-- ── 2. POLÍTICAS DE ACESSO ──
-- O painel usa a chave pública ("anon"), então todo acesso vem como
-- usuário anônimo. Essas policies liberam leitura e escrita para esse perfil.

alter table acordos_trade   enable row level security;
alter table parcelas_acordo enable row level security;
alter table kb_tarefas      enable row level security;

drop policy if exists "public_all"           on acordos_trade;
drop policy if exists "public_all_parcelas"  on parcelas_acordo;
drop policy if exists "public_all_tarefas"   on kb_tarefas;

create policy "public_all"          on acordos_trade   for all using (true) with check (true);
create policy "public_all_parcelas" on parcelas_acordo for all using (true) with check (true);
create policy "public_all_tarefas"  on kb_tarefas      for all using (true) with check (true);

-- ── 3. CARGA DA BASE REAL ──
-- Remove qualquer dado anterior e insere os 114 acordos e 410 parcelas.

delete from parcelas_acordo;
delete from acordos_trade;


